            openFuzzingFindingRunDeletedElsewhere: '正在回放的发现项所属的探索运行已被删除（可能来自 AI 助手或另一个标签页），回放已结束。如需候选证据，请重新运行探索。',
            // 模型轨迹同样自成一类：它既不是结论也不是候选发现，而是一段可回放的执行过程，
