            deviceVariablesHint: 'Quantities the device template declares. An environment variable is shared by the scenario, and its value and labels are owned by the Environment Pool; an internal variable belongs to this device instance and can be overridden in Instance Configuration above. One marked affects-only is written but not read by this device, so it cannot be a condition source for its rules or specifications.',
            deviceStates: 'States',
            deviceStatesHint: 'The values the state machine can take. Labels are declared per state and may differ (a phone is private while taking a photo and public when merely on); they propagate along automation when a rule fires. Variable value is what a variable holds while the state is active, not an action taken once. Where it repeats the state name (a Car in `garage` holds `location = garage`) that is the reported-reading mirror a rule reads — under compromise it can diverge from the true state.',
